import{_ as s,l as n,o as e,c as o,v as t,p as l,x as r,d as E,i as d,S as A}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"老化与可靠性","description":"","frontmatter":{"title":"老化与可靠性","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/aging-reliability.md","filePath":"cs/aging-reliability.md","lastUpdated":1789023840000}'),p={name:"cs/aging-reliability.md"};function c(h,a,B,C,D,T){const i=n("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="老化与可靠性" tabindex="-1">老化与可靠性 <a class="header-anchor" href="#老化与可靠性" aria-label="Permalink to &quot;老化与可靠性&quot;">​</a></h1><div class="epigraph"><p>NBTI、热载流子、电迁移让阈值漂、连线变脆：昨天 STA 过的路径，几年后在高温高电压下可能建立失败，这不是一次粒子事件。</p><footer>—— 据 Weste and Harris, CMOS VLSI Design；JEDEC 可靠性应力标准实践；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/soft-error-ecc">上一课</a>处理随机瞬时翻转。DFT/BIST 处理出厂缺陷。<a href="/cs/power-dynamic-static">功耗</a>带来热。缺口是<strong>时间尺度上的漂移</strong>：老化让延迟和漏电变，可靠性要在签核时留边，而不是只信零时刻库。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>NBTI/PBTI：偏置温度下阈值升高，PMOS/NMOS 变慢。HCI：热载流子损伤沟道。TDDB：栅氧击穿。电迁移：大电流金属孔洞。EM 与电流密度、温度有关，宽算术总线和时钟树是热点。缺口不是再设计 ECC，而是：STA 要用老化后的延迟库或余量，电流密度检查在物理签核里。</p><p>与 Dennard 墙相关：更高的功耗密度加速热老化。DVFS 降 \\(V\\) 可减缓部分机制，又与性能折中。</p><h3 id="老化不是软错误" tabindex="-1">老化不是软错误 <a class="header-anchor" href="#老化不是软错误" aria-label="Permalink to &quot;老化不是软错误&quot;">​</a></h3><p>软错误可纠正且器件仍好。老化是参数永久（或准永久，有恢复）漂移。把 FIT 粒子率当成 MTTF 老化，维修策略会错：ECC 救不了整条时钟树变慢。</p><p><span class="marginnote">Weste/Harris 讨论可靠性机制。JEDEC 有高温工作寿命等应力试验方法（本课不背编号清单）。CA:AQA 把可用性作为系统指标。本课不编造某工艺的寿命小时数。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>签核：电压温度老化角、电迁移规则、余量。设计：宽金属、冗余过孔、降低热点电流、自适应电压（相对 DVFS 更慢的补偿环）。现场：温度传感器、降频保活，与 BIST 定期自检互补。SRAM 稳定性随老化变差，最低电压要留裕量。</p>',11)),(e(),l(A,null,{default:r(()=>[d(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20STR%5B%22%E7%94%B5%E5%8E%8B%20%E6%B8%A9%E5%BA%A6%20%E7%94%B5%E6%B5%81%22%5D%20--%3E%20MECH%5B%22NBTI%20%2F%20HCI%20%2F%20EM%22%5D%0A%20%20MECH%20--%3E%20DLY%5B%22%E5%BB%B6%E8%BF%9F%E4%B8%8E%E6%BC%8F%E7%94%B5%E6%BC%82%E7%A7%BB%22%5D%0A%20%20DLY%20--%3E%20MARGIN%5B%22STA%20%E4%BD%99%E9%87%8F%E4%B8%8E%E9%99%8D%E9%A2%9D%22%5D%0A%20%20MARGIN%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9ADRAM%20%E6%8E%A5%E5%8F%A3%E7%9A%84%E5%8F%A6%E4%B8%80%E5%A5%97%E6%97%B6%E5%BA%8F%E5%90%88%E5%90%8C%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>HDL 课序到此封口：从 Verilog 到网表、时序、时钟、复位、CDC、FPGA/ASIC、功耗、经济、验证、测试、软错误与老化。下一单元内存与 I/O 把这些块接到 JEDEC 与 PCIe 的真实协议。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>DRAM 刷新本身也是对抗漏电的可靠性机制，但规格在 JEDEC，不在 CMOS 老化公式里。PCIe SERDES 有自己的眼图老化。本课只钉数字 CMOS 参数漂移，让后课接口规范的时序是「寿命期内仍要满足」。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不推导反应–扩散 NBTI 方程，不写封装焊点疲劳的力学。不进入光刻胶老化。不把金融「可靠性」隐喻写进来。</p><p>后课默认：时序签核含老化余量；软错误与老化分机制；数字系统实现课序结束，改接 DRAM 组织。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>老化是延迟/漏电/连线的缓慢损伤，不是 SEU。</li><li>签核用余量与电流密度规则；现场可降额。</li><li>HDL 实现单元收束，下一课通道/rank/bank。</li><li>出处：Weste and Harris；JEDEC 应力实践；Hennessy and Patterson, CA:AQA。</li></ul>',8))])}const m=s(p,[["render",c]]);export{S as __pageData,m as default};
